<?php require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/pdf_generator.php';checkAuth(['economia','admin']);$db=getDBConnection();$date=date('Y-m-d');$msg='';$open=$db->query("SELECT * FROM cajas WHERE estado='abierta' ORDER BY id DESC LIMIT 1")->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['abrir'])&&!$open){$s=$db->prepare('INSERT INTO cajas(fecha,usuario_apertura,apertura_cup,estado) VALUES(?,?,?,\'abierta\')');$s->execute([$date,$_SESSION['usuario']['id'],numberValue($_POST['apertura']??0)]);$open=$db->query("SELECT * FROM cajas WHERE estado='abierta' ORDER BY id DESC LIMIT 1")->fetch();$msg='Caja abierta.';}elseif(isset($_POST['cerrar'])&&$open){$s=$db->prepare("SELECT COALESCE(SUM(monto_cup),0) FROM movimientos_caja WHERE caja_id=? AND tipo IN('venta','entrada')");$s->execute([$open['id']]);$ventas=(float)$s->fetchColumn();$s=$db->prepare("SELECT COALESCE(SUM(monto_cup),0) FROM movimientos_caja WHERE caja_id=? AND tipo='salida'");$s->execute([$open['id']]);$salidas=(float)$s->fetchColumn();$esperado=(float)$open['apertura_cup']+$ventas-$salidas;$declarado=numberValue($_POST['declarado']??0);$num=nextNumber('CIERRE-');$path=generarDocumentoPDF('cierre_caja',$num,'Cierre de caja',['Apertura: '.money($open['apertura_cup']),'Ventas/entradas: '.money($ventas),'Salidas: '.money($salidas),'Efectivo esperado: '.money($esperado),'Efectivo declarado: '.money($declarado),'Diferencia: '.money($declarado-$esperado)]);$db->prepare('UPDATE cajas SET estado=\'cerrada\',fecha_cierre=?,usuario_cierre=?,efectivo_esperado=?,efectivo_declarado=?,diferencia=?,pdf_path=? WHERE id=?')->execute([now(),$_SESSION['usuario']['id'],$esperado,$declarado,$declarado-$esperado,$path,$open['id']]);storeDocument('cierre_caja',$open['id'],$num,$path);$msg='Caja cerrada y PDF guardado.';$open=null;}}$summary=$db->query("SELECT COALESCE(SUM(CASE WHEN metodo_pago='efectivo' THEN monto_total_cup ELSE 0 END),0) efectivo,COALESCE(SUM(CASE WHEN metodo_pago='transferencia' THEN monto_total_cup ELSE 0 END),0) transfer,COALESCE(SUM(monto_total_cup),0) total FROM facturas WHERE tipo='comprobante' AND date(fecha)='$date'")->fetch();?><div class="card"><h1>Cuadre de caja</h1><div class="grid grid-3"><div class="stat">Efectivo ventas<strong><?=money($summary['efectivo'])?></strong></div><div class="stat">Transferencias<strong><?=money($summary['transfer'])?></strong></div><div class="stat">Total ventas<strong><?=money($summary['total'])?></strong></div></div><?php if($msg):?><div class="notice" style="margin-top:15px"><?=h($msg)?></div><?php endif;?><?php if(!$open):?><form method="post" class="actions" style="margin-top:18px"><input type="hidden" name="abrir" value="1"><input type="number" step="0.01" name="apertura" placeholder="Fondo de caja inicial CUP" required><button class="btn gold">Abrir caja</button></form><?php else:?><div class="notice" style="margin-top:18px">Caja abierta desde <?=h($open['fecha'])?> · fondo <?=money($open['apertura_cup'])?></div><form method="post" class="actions"><input type="hidden" name="cerrar" value="1"><input type="number" step="0.01" name="declarado" placeholder="Efectivo físico contado" required><button class="btn danger" data-confirm="¿Cerrar definitivamente la caja?">Cerrar caja y generar PDF</button></form><?php endif;?></div><?php require_once __DIR__.'/../includes/footer.php';?>
